/// Launch LAN discovery plus optional routed-query handling on the same UDP socket.
pub fn spawn_discovery_with_routed(
    socket: Arc<UdpSocket>,
    roster: Arc<Mutex<Roster>>,
    announce: SharedAnnounce,
    self_user_id: String,
    discovery_port: u16,
    trigger: Option<Arc<Notify>>,
    visibility: Arc<DiscoveryVisibility>,
    routed: Option<Arc<RoutedDiscovery>>,
) -> Vec<JoinHandle<()>> {
    spawn_discovery_with_network_changes(
        socket,
        roster,
        announce,
        self_user_id,
        discovery_port,
        trigger,
        visibility,
        routed,
        None,
    )
}

pub(crate) fn spawn_discovery_with_network_changes(
    socket: Arc<UdpSocket>,
    roster: Arc<Mutex<Roster>>,
    announce: SharedAnnounce,
    self_user_id: String,
    discovery_port: u16,
    trigger: Option<Arc<Notify>>,
    visibility: Arc<DiscoveryVisibility>,
    routed: Option<Arc<RoutedDiscovery>>,
    network_changes: Option<tokio::sync::watch::Sender<u64>>,
) -> Vec<JoinHandle<()>> {
    let trigger = trigger.unwrap_or_else(|| Arc::new(Notify::new()));
    let target: SocketAddr = (
        crate::transport::net::DISCOVERY_MULTICAST_GROUP,
        discovery_port,
    )
        .into();
    vec![
        tokio::spawn(run_listen_with_routed(
            Arc::clone(&socket),
            roster,
            self_user_id,
            Arc::clone(&announce),
            discovery_port,
            Arc::clone(&visibility),
            routed,
        )),
        tokio::spawn(run_broadcast_with_visibility(
            Arc::clone(&socket),
            Arc::clone(&announce),
            target,
            Duration::from_secs(2),
            Some(Arc::clone(&trigger)),
            Arc::clone(&visibility),
        )),
        tokio::spawn(run_scan_with_visibility(
            Arc::clone(&socket),
            announce,
            discovery_port,
            Some(Arc::clone(&trigger)),
            visibility,
        )),
        tokio::spawn(run_rejoin(socket, trigger, network_changes)),
    ]
}

/// IPv6 uses unicast only; the existing IPv4 LAN multicast loop remains separate.
pub fn spawn_routed_listener(
    socket: Arc<UdpSocket>,
    roster: Arc<Mutex<Roster>>,
    announce: SharedAnnounce,
    self_user_id: String,
    discovery_port: u16,
    visibility: Arc<DiscoveryVisibility>,
    routed: Arc<RoutedDiscovery>,
) -> JoinHandle<()> {
    tokio::spawn(run_listen_with_routed(
        socket,
        roster,
        self_user_id,
        announce,
        discovery_port,
        visibility,
        Some(routed),
    ))
}

