#[tokio::test]
async fn pairing_previously_known_foreign_device_survives_both_runtime_restarts() {
    let dir = tempfile::tempdir().unwrap();
    let start_reserved = async |owner: &str| {
        // Retain a compatible reservation until the runtime owns this port.
        let reservation = crate::transport::net::discovery_socket(0).unwrap();
        let running = start(dir.path(), owner, reservation.local_addr().unwrap().port()).await;
        running.0.participant.discovery_trace().enable_trace();
        drop(reservation);
        running
    };
    let (alice, _) = start_reserved("pair-owner").await;
    let (bob, _) = start_reserved("pair-joiner").await;
    let alice_id = alice.user_id().to_owned();
    let bob_id = bob.user_id().to_owned();
    let account = alice.account_id().to_owned();
    assert_ne!(account, bob.account_id());
    discover("before pairing: owner learns joiner", &alice, &bob)
        .await
        .unwrap();
    discover("before pairing: joiner learns owner", &bob, &alice)
        .await
        .unwrap();
    // Force the prior account proof to durable storage before explicit pairing.
    alice.handle().cached_peer_snapshot_async().await.unwrap();
    let code = alice.start_linking();
    let pairing_target = bob
        .roster
        .lock()
        .unwrap()
        .get(&alice_id)
        .cloned()
        .expect("discovery established the certified pairing target");
    let linked = bob.link_device(&alice_id, &code).await;
    assert!(
        linked.is_ok(),
        "known-peer pairing failed: result={linked:?}; linker_user_id={alice_id}; joiner_user_id={bob_id}; certified_account={:?}; roster_target={}; routes={:?}; linker_tcp={}; linker_udp={}; joiner_tcp={}; joiner_udp={}",
        pairing_target.account_id,
        pairing_target.addr,
        pairing_target.routes,
        alice.listen_tcp_port(),
        alice.discovery_port(),
        bob.listen_tcp_port(),
        bob.discovery_port(),
    );
    assert_eq!(linked.unwrap(), account);
    bob.stop().await;
    alice.stop().await;
    let (alice, _) = start_reserved("pair-owner").await;
    let (bob, _) = start_reserved("pair-joiner").await;
    assert_eq!(bob.user_id(), bob_id);
    assert_eq!(bob.account_id(), account);
    discover("after restart: owner learns adopted joiner", &alice, &bob)
        .await
        .unwrap();
    discover("after restart: adopted joiner learns owner", &bob, &alice)
        .await
        .unwrap();
    let (contact, _) = start_reserved("pair-contact").await;
    // Bob and this new contact model separate machines but share 127.0.0.1.
    // Alice's ResponseBudget admits only one query response per source IP per
    // second. Let Bob's response window expire before the contact's first query,
    // so its unchanged six-second deadline covers an eligible challenge.
    tokio::time::sleep(Duration::from_secs(1)).await;
    discover("after restart: contact learns owner", &contact, &alice)
        .await
        .unwrap();
    contact
        .send_to_account(&account, b"after both restarts", None)
        .await
        .unwrap();
    tokio::time::timeout(Duration::from_secs(15), async {
        loop {
            if bob
                .account_history(contact.account_id(), 10)
                .unwrap()
                .iter()
                .any(|entry| entry.text == b"after both restarts")
            {
                break;
            }
            tokio::time::sleep(Duration::from_millis(40)).await;
        }
    })
    .await
    .expect("ongoing certified sibling history synchronization");
    contact.stop().await;
    bob.stop().await;
    alice.stop().await;
}

    /// Own the visibility lease and its I/O together so a stalled UDP socket
    /// cannot postpone a privacy change indefinitely. The future is only polled
    /// after admission, and cancellation drops it before releasing the lease.
    pub(crate) async fn with_routed_send<T>(
        &self,
        send: impl Future<Output = io::Result<T>>,
    ) -> io::Result<Option<T>> {
        self.with_send(true, send).await
    }

    async fn with_send<T>(
        &self,
        routed: bool,
        send: impl Future<Output = io::Result<T>>,
    ) -> io::Result<Option<T>> {
        tokio::time::timeout(SEND_TIMEOUT, async {
            let public = self.public.read().await;
            if !*public || (routed && self.physical_lan_only()) {
                return Ok(None);
            }
            let result = send.await;
            drop(public);
            result.map(Some)
        })
        .await
        .map_err(|_| io::Error::new(io::ErrorKind::TimedOut, "discovery send timed out"))?
    }

    pub async fn routed_allowed(&self) -> bool {
        *self.public.read().await && !self.physical_lan_only()
    }

